import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CalibrationSequence } from "@/pages/calibration/calibration-sequence";
import { JointControl } from "@/pages/calibration/joint-control";
import { MotorSetup } from "@/pages/calibration/motor-setup";
import { QuickCalibrate } from "@/pages/calibration/quick-calibrate";

export function CalibrationPage() {
  return (
    <Tabs defaultValue="setup">
      <TabsList className="grid w-full grid-cols-4">
        <TabsTrigger value="setup">Setup</TabsTrigger>
        <TabsTrigger value="quick-calibrate">Calibration</TabsTrigger>
        <TabsTrigger value="advanced-calibrate">Advanced Cal.</TabsTrigger>
        <TabsTrigger value="joint-control">Joints Control</TabsTrigger>
      </TabsList>
      <TabsContent value="setup">
        <MotorSetup />
      </TabsContent>
      <TabsContent value="quick-calibrate">
        <QuickCalibrate />
      </TabsContent>
      <TabsContent value="advanced-calibrate">
        <CalibrationSequence />
      </TabsContent>
      <TabsContent value="joint-control">
        <JointControl />
      </TabsContent>
    </Tabs>
  );
}
